def insertion_sort(values):
    for index in range(1, len(values)):
        key = values[index]            # item to insert into sorted part
        position = index - 1
        while position >= 0 and values[position] > key:
            values[position + 1] = values[position]   # shift right
            position = position - 1
        values[position + 1] = key     # drop key into the gap
    return values

print(insertion_sort([29, 12, 41, 7, 18, 33]))  # [7, 12, 18, 29, 33, 41]

class TreeNode:
    def __init__(self, key):
        self.key = key
        self.left = None               # None is the null pointer
        self.right = None

def insert(root, key):
    if root is None:
        return TreeNode(key)           # empty place found: new leaf
    if key < root.key:
        root.left = insert(root.left, key)
    else:
        root.right = insert(root.right, key)
    return root

def find(root, target):
    current = root
    while current is not None and current.key != target:
        if target < current.key:
            current = current.left
        else:
            current = current.right
    return current                     # None if not found

root = None
for key in ["K", "D", "R", "B", "G", "M"]:
    root = insert(root, key)
print(find(root, "G").key, find(root, "Q"))  # G None

class Stack:
    def __init__(self, size=8):
        self.items = [None] * size     # fixed-size array
        self.top = -1                  # top pointer: -1 means empty

    def push(self, item):
        if self.top == len(self.items) - 1:
            return False               # overflow: stack full
        self.top = self.top + 1
        self.items[self.top] = item
        return True

    def pop(self):
        if self.top == -1:
            return None                # underflow: stack empty
        item = self.items[self.top]
        self.top = self.top - 1
        return item

    def peek(self):
        if self.top == -1:
            return None
        return self.items[self.top]

s = Stack(3)
print(s.push("X"), s.push("Y"), s.push("Z"), s.push("W"))  # True True True False
print(s.pop(), s.peek())  # Z Y

class Stack:                           # minimal stack ADT
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def is_empty(self):
        return self.items == []


class QueueUsingTwoStacks:
    def __init__(self):
        self.inbox = Stack()           # receives new items
        self.outbox = Stack()          # gives items out in FIFO order

    def enqueue(self, item):
        self.inbox.push(item)

    def dequeue(self):
        if self.outbox.is_empty():
            while not self.inbox.is_empty():   # reverse the order once
                self.outbox.push(self.inbox.pop())
        if self.outbox.is_empty():
            return None                # queue empty
        return self.outbox.pop()

q = QueueUsingTwoStacks()
for job in ["P1", "P2", "P3"]:
    q.enqueue(job)
print(q.dequeue(), q.dequeue())  # P1 P2
q.enqueue("P4")
print(q.dequeue(), q.dequeue(), q.dequeue())  # P3 P4 None
